  Governor, GovernorCountingSimple, GovernorVotes,
  GovernorVotesQuorumFraction, GovernorTimelockControl
{
  constructor(IVotes token, TimelockController timelock)
    Governor("ProjectGovernor") GovernorVotes(token)
    GovernorVotesQuorumFraction(4) GovernorTimelockControl(timelock)
  {}
}

function state(uint256 id) public view
  override(Governor, GovernorTimelockControl)
  returns (ProposalState)
{ return super.state(id); }
function _executor() internal view
  override(Governor, GovernorTimelockControl)
  returns (address)
{ return super._executor(); }
